from collections import deque

def min_path(x1, y1, x2, y2):
    queue = deque([(x1, y1, 0)])
    visited = set()
    visited.add((x1, y1))

    while queue:
        x, y, dist = queue.popleft()

        if x == x2 and y == y2:
            # Find the closest point on the boundary
            min_dist = float('inf')
            for dx in [-1, 0, 1]:
                for dy in [-1, 0, 1]:
                    if dx != 0 or dy != 0:
                        nx, ny = x + dx, y + dy
                        if (nx, ny) not in visited:
                            min_dist = min(min_dist, abs(nx - x2) + abs(ny - y2))
            return dist + min_dist * 2

        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy
            if -100 <= nx <= 100 and -100 <= ny <= 100 and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

# Example usage
if __name__ == "__main__":
    x1, y1 = map(int, input().split())
    x2, y2 = map(int, input().split())
    print(min_path(x1, y1, x2, y2))
